module bench/retention v1.0.0;
import "db/sqlite" take SqliteMemory;
import "db/query" take Query;
import "db/statement" take Statement;
import "os/environment" take Environment;
import "strings/parse" take ParsedInt;
import "io/stdout" take Stdout;
async main() is int {
 let connection=await SqliteMemory().connection();
 defer await connection.settled();defer connection.close();
 let count=ParsedInt(Environment().variable("COUNT")).value();
 for 0..count -> i {
  let row=await Query(connection,Statement("SELECT zeroblob(1048576) AS payload")).one();
  confirm row.size()==1 else panic "wrong row";
 }
 Stdout().writeln("ok "+count.string());
 0;
}

